"use client";

import React from "react";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface BorderBeamProps {
  className?: string;
  size?: number;
  duration?: number;
  colorFrom?: string;
  colorTo?: string;
}

/**
 * Magic UI BorderBeam
 * Source: https://magicui.design/docs/components/border-beam
 * Pure CSS/SVG traveling perimeter highlight.
 * Zero external JS dependencies.
 * Respects prefers-reduced-motion.
 */
export const BorderBeam: React.FC<BorderBeamProps> = ({
  className,
  size = 250,
  duration = 12,
  colorFrom = "#f43f5e",
  colorTo = "#3b82f6",
}) => {
  return (
    <div
      className={cn(
        "pointer-events-none absolute inset-0 rounded-[inherit] overflow-hidden motion-reduce:hidden",
        className
      )}
      aria-hidden="true"
    >
      <div
        className="absolute inset-[-100%] animate-[spin_10s_linear_infinite] motion-reduce:animate-none opacity-40"
        style={{
          background: `conic-gradient(from 0deg at 50% 50%, transparent 0deg, ${colorFrom} 60deg, ${colorTo} 120deg, transparent 180deg)`,
        }}
      />
    </div>
  );
};

export default BorderBeam;
