/**
 * Pan-India Train Class Resolution Engine
 *
 * Authoritatively maps train numbers, types, and operational compositions
 * to their authentic Indian Railways classes (e.g. SL, 3A, 2A, 1A, CC, EC, 2S, 3E, EA).
 *
 * Prevents invalid API requests (e.g. requesting SL on Vande Bharat/Shatabdi/Rajdhani/Intercity)
 * which trigger HTTP 400 errors from RailKit/IRCTC, and ensures passengers see
 * genuine coach options on ALL Pan-India trains (including mixed trains like 11139 CSMT-HPT).
 */

export interface TrainMinimal {
  trainNumber?: string;
  trainName?: string;
  trainNo?: string;
  train_no?: string;
  name?: string;
  classes?: any[];
}

