// Backward-compatible alias
export const KNOWN_TRAIN_CLASSES = EXPLICIT_TRAIN_OVERRIDES;

/**
 * Resolves valid coach classes based on Train Number, Name keywords, and dynamic live errors.
 *
 * @param train Train object containing trainNumber/trainNo, trainName, or classes array.
 * @param failedClasses Optional array of classes that failed dynamically with HTTP 400 from RailKit.
 * @returns Array of valid coach class codes (e.g. ['SL', 'CC', '3A', '2A', '1A'])
 */
export const getTrainSupportedClasses = (
  train: TrainMinimal | any,
  failedClasses?: string[]
): string[] => {
  if (!train) return ['SL', '3A', '2A', '1A'];

  // 1. Explicit classes already attached to train object
  if (Array.isArray(train.classes) && train.classes.length > 0) {
    const valid = train.classes
      .map((c: any) => (typeof c === 'string' ? c : c.class || c.code || ''))
      .filter(Boolean)
      .map((c: string) => c.toUpperCase().trim());
    if (valid.length > 0) {
      let result: string[] = Array.from(new Set(valid));
      if (failedClasses && failedClasses.length > 0) {
        result = result.filter((c: string) => !failedClasses.includes(c));
      }
      return result;
    }
  }

  const rawNo = String(
    train.trainNumber ||
    train.trainNo ||
    train.train_no ||
    train.train_number ||
    train.number ||
    ''
  ).trim();
  const cleanNo = rawNo.replace(/^0+/, '');

  let classes: string[] = [];

  // 2. Check explicit hybrid overrides first
  if (EXPLICIT_TRAIN_OVERRIDES[cleanNo]) {
    classes = [...EXPLICIT_TRAIN_OVERRIDES[cleanNo]];
  } else if (EXPLICIT_TRAIN_OVERRIDES[rawNo]) {
    classes = [...EXPLICIT_TRAIN_OVERRIDES[rawNo]];
  } else {
    const name = String(
      train.trainName || train.train_name || train.name || ''
    ).toUpperCase().trim();

    // 3. Keyword matching for strict elite/specific trains across India
    if (name.includes('VANDE BHARAT') || name.includes('VANDEBHARAT')) {
      classes = ['CC', 'EC'];
    } else if (
      name.includes('SHATABDI') ||
      name.includes('TEJAS EXP') ||
      name.includes('GATIMAAN')
    ) {
      classes = ['CC', 'EC', 'EA']; // Includes Anubhuti (EA) for Premium Shatabdi
    } else if (name.includes('JAN SHATABDI') || name.includes('JANSHATABDI')) {
      classes = ['2S', 'CC'];
    } else if (name.includes('DOUBLE DECKER') || name.includes('UDAY')) {
      classes = ['CC', 'EC'];
    } else if (name.includes('GARIB RATH') || name.includes('GARIBRATH')) {
      classes = ['3A', 'CC']; // No SL, 2A, 1A for Garib Rath
    } else if (
      name.includes('RAJDHANI') ||
      name.includes('TEJAS RAJ') ||
      name.includes('DURONTO AC') ||
      name.includes('AC DURONTO') ||
      name.includes('AC EXP') ||
      name.includes('AC SF') ||
      name.includes('AC SUPERFAST')
    ) {
      classes = ['3A', '2A', '1A']; // Fully AC Premium, no Sleeper
    } else if (name.includes('HUMSAFAR')) {
      classes = ['3E', '3A', 'SL']; // Includes AC 3-Tier Economy (3E)
    } else if (name.includes('AMRIT BHARAT')) {
      classes = ['SL', '2S']; // Non-AC Sleeper & General only
    } else if (name.includes('YUVA')) {
      classes = ['CC', '3A'];
    } else if (name.includes('INTERCITY') || name.includes('INTER CITY')) {
      // Day intercity express trains across India
      classes = ['2S', 'CC', '3A'];
    } else if (name.includes('ANTYODAYA')) {
      classes = ['2S'];
    } else {
      // Standard dynamic Pan-India Mail/Express/Superfast configuration
      classes = ['SL', '3A', '2A', '1A'];
    }
  }

  // 4. Dynamic Filtering: Drop classes that threw an active RailKit HTTP 400 error
  if (failedClasses && failedClasses.length > 0) {
    classes = classes.filter((c) => !failedClasses.includes(c));
  }

  return classes.length > 0 ? classes : ['SL', '3A', '2A', '1A'];
};

/**
 * Prevents UI crashes by picking a safe fallback active tab if searched class is missing.
 *
 * @param supportedClasses Valid classes for this train
 * @param requestedClass Class requested by user (e.g. 'SL')
 */
export const getDefaultActiveClass = (
  supportedClasses: string[],
  requestedClass?: string
): string => {
  if (!supportedClasses || supportedClasses.length === 0) return 'SL';
  const req = (requestedClass || '').toUpperCase().trim();
  if (req && supportedClasses.includes(req)) return req;

  // Smart fallbacks for user experience
  if (req === 'SL') {
    if (supportedClasses.includes('3A')) return '3A';
    if (supportedClasses.includes('CC')) return 'CC';
    if (supportedClasses.includes('2S')) return '2S';
  }

  if (req === 'CC') {
    if (supportedClasses.includes('EC')) return 'EC';
    if (supportedClasses.includes('2S')) return '2S';
  }

  // General fallback order
  if (supportedClasses.includes('SL')) return 'SL';
  if (supportedClasses.includes('3A')) return '3A';
  if (supportedClasses.includes('CC')) return 'CC';
  if (supportedClasses.includes('2S')) return '2S';
  return supportedClasses[0] || 'SL';
};
