"use client";

import React, { useState, useEffect } from "react";
import clsx from "clsx";
import { AlertTriangle, ChevronDown, ChevronUp, ShieldCheck, X } from "lucide-react";
import { getIstCurrentMinutes, getIstTime } from "@/lib/istTimeUtils";

interface IrctcTrafficTelemetryProps {
  className?: string;
}

/**
 * IrctcTrafficTelemetry
 * Informs travelers during critical Tatkal rush hours when upstream Indian Railways
 * servers face peak concurrency.
 *
 * Schedule (Appears strictly during morning rush windows, hidden rest of day):
 * - Window 1: 09:30 AM – 10:15 AM IST (AC Tatkal Rush)
 * - Window 2: 10:50 AM – 11:20 AM IST (Non-AC Tatkal Rush)
 */
export function IrctcTrafficTelemetry({ className }: IrctcTrafficTelemetryProps) {
  const [dismissed, setDismissed] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [mins, setMins] = useState<number>(() => getIstCurrentMinutes());
  const [istFormatted, setIstFormatted] = useState<string>(() => getIstTime().formattedTime);

  useEffect(() => {
    const updateTime = () => {
      if (document.visibilityState === "visible") {
        setMins(getIstCurrentMinutes());
        setIstFormatted(getIstTime().formattedTime);
      }
    };

    updateTime();
    const interval = setInterval(updateTime, 15000);
    return () => clearInterval(interval);
  }, []);

  // Tatkal Rush Windows (IST):
  // Window 1 (AC Tatkal): 09:30 AM (570m) to 10:15 AM (615m)
  // Window 2 (Non-AC Tatkal): 10:50 AM (650m) to 11:20 AM (680m)
  const isAcRush = mins >= 570 && mins <= 615;
  const isNonAcRush = mins >= 650 && mins <= 680;
  const isRush = isAcRush || isNonAcRush;

  // Banner strictly shows ONLY during the morning rush windows.
  // Outside these windows (rest of the day), it remains hidden.
  if (dismissed || !isRush) return null;

  return (
    <div
      className={clsx(
        "rounded-2xl border transition-all duration-300 p-3.5 sm:p-4 text-xs select-none backdrop-blur-md bg-amber-500/10 border-amber-500/30 text-amber-900 dark:text-amber-100 shadow-sm animate-fade-in",
        className
      )}
    >
      <div className="flex items-center justify-between gap-3">
        {/* Left: Status Indicator & Title */}
        <div className="flex items-center gap-2.5 min-w-0">
          {/* Animated Status Pulse */}
          <span className="relative flex h-2.5 w-2.5 shrink-0 items-center justify-center">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75" />
            <span className="relative inline-flex rounded-full h-2 w-2 bg-amber-500" />
          </span>

          <div className="flex items-center gap-2 flex-wrap">
            <span className="font-bold text-main flex items-center gap-1.5">
              <AlertTriangle className="w-3.5 h-3.5 text-amber-500 shrink-0" />
              <span>
                {isAcRush
                  ? "IRCTC AC Tatkal Rush Window Active"
                  : "IRCTC Sleeper / Non-AC Tatkal Rush Active"}
              </span>
            </span>

            {/* Micro telemetry tag */}
            <span className="px-2 py-0.5 rounded-full text-[10px] font-mono font-bold tracking-tight bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30">
              {isAcRush ? "09:30 – 10:15 AM IST" : "10:50 – 11:20 AM IST"}
            </span>

            <span className="text-[10px] font-mono text-muted hidden sm:inline">
              ({istFormatted})
            </span>
          </div>
        </div>

        {/* Right: Expand Toggle & Dismiss */}
        <div className="flex items-center gap-1.5 shrink-0">
          <button
            type="button"
            onClick={() => setExpanded(!expanded)}
            className="p-1 rounded-lg hover:bg-card text-muted hover:text-main transition-colors cursor-pointer"
            aria-label={expanded ? "Collapse details" : "Expand telemetry details"}
            title="Toggle details"
          >
            {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>
          <button
            type="button"
            onClick={() => setDismissed(true)}
            className="p-1 rounded-lg hover:bg-card text-muted hover:text-main transition-colors cursor-pointer"
            aria-label="Dismiss telemetry alert"
            title="Dismiss"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {/* Expanded Telemetry & Advisory Details */}
      {expanded && (
        <div className="mt-3 pt-3 border-t border-amber-500/20 flex flex-col gap-2 text-[11px] leading-relaxed animate-in fade-in duration-200 text-amber-800 dark:text-amber-200/90">
          <p>
            <strong>Upstream Server Advisory:</strong> Indian Railways and IRCTC servers experience high concurrent traffic during morning Tatkal booking hours. Real-time availability checks may take 3–5 seconds to synchronize.
          </p>
          <div className="flex items-center gap-2 text-[10px] font-semibold text-muted pt-1">
            <ShieldCheck className="w-3.5 h-3.5 text-emerald-500 shrink-0" />
            <span>Trayago searches available direct and split routes. Final ticket booking redirects directly to official IRCTC.</span>
          </div>
        </div>
      )}
    </div>
  );
}

export default IrctcTrafficTelemetry;
