export interface ClientBookingContext {
  fromStation: string;
  toStation: string;
  trainNo?: string;
  journeyDate?: string;
  classType?: string;
  quota?: string;
  utmSource?: string;
  utmCampaign?: string;
  partnerId?: string;
  campaignId?: string;
}

export interface ClientBookingResult {
  url: string;
  providerId: string;
  displayName: string;
  isOfficial: boolean;
}

export class ClientBookingResolver {
  private defaultProviderId = 'IRCTC';

  /**
   * Generates client-side booking redirect URL based on active provider configuration.
   */
  public generateBookingUrl(context: ClientBookingContext): ClientBookingResult {
    const fromStation = (context.fromStation || '').trim().toUpperCase();
    const toStation = (context.toStation || '').trim().toUpperCase();
    const trainNo = (context.trainNo || '').trim();
    const journeyDate = (context.journeyDate || '').trim();

    const params = new URLSearchParams();

    if (fromStation) params.set('fromStation', fromStation);
    if (toStation) params.set('toStation', toStation);
    if (trainNo && trainNo !== 'Not Available' && trainNo !== 'XXXXX') {
      params.set('trainNo', trainNo);
    }
    if (journeyDate) params.set('journeyDate', journeyDate);

    params.set('utm_source', context.utmSource || 'trayago');
    params.set('utm_campaign', context.utmCampaign || 'ai_booking');

    if (context.partnerId) params.set('partner_id', context.partnerId);
    if (context.campaignId) params.set('campaign_id', context.campaignId);

    const url = `https://www.irctc.co.in/nget/train-search?${params.toString()}`;

    return {
      url,
      providerId: 'IRCTC',
      displayName: 'IRCTC Official Booking',
      isOfficial: true
    };
  }
}

export const clientBookingResolver = new ClientBookingResolver();
